import os
import torch


class Config:
    """
    Configuration class for the RNA Degradation Prediction task.
    Implements settings for the SWA-Optimized Pre-Mixed Wide-Stream BiGRU.
    """

    # ==========================
    # General Settings
    # ==========================
    PROJECT_NAME = "RNA_Degradation_Prediction"
    IDEA_NAME = "idea_24"
    SEED = 42
    DEVICE = "cuda" if torch.cuda.is_available() else "cpu"
    NUM_WORKERS = 4

    # ==========================
    # Data Paths
    # ==========================
    # Metadata paths (Parquet files generated by metadata script)
    TRAIN_DATA_PATH = "./metadata/train.parquet"
    VAL_DATA_PATH = "./metadata/val.parquet"
    TEST_DATA_PATH = "./metadata/test.parquet"

    # Raw input paths
    SAMPLE_SUBMISSION_PATH = "./input/sample_submission.csv"

    # Output paths
    WORKING_DIR = os.path.join("./working", IDEA_NAME)
    CACHE_DIR = WORKING_DIR  # Directory to store processed tensors
    MODEL_SAVE_PATH = os.path.join(WORKING_DIR, "best_model.pth")
    SUBMISSION_DIR = "./submission"
    SUBMISSION_PATH = os.path.join(SUBMISSION_DIR, "submission.csv")

    # ==========================
    # Data Dimensions & Vocab
    # ==========================
    SEQ_LEN = 107
    PRED_LEN = 68

    # Vocabulary mappings
    # Sequence: A, G, C, U
    VOCAB_SIZE_SEQ = 4
    # Loop Type: S, M, I, B, H, E, X
    VOCAB_SIZE_LOOP = 7

    # ==========================
    # Model Hyperparameters
    # ==========================
    # Embedding Dimensions
    EMBED_DIM_SEQ = 32
    EMBED_DIM_LOOP = 32
    EMBED_DIM_DIST = 32  # Dimension for Signed Sinusoidal Pairing Distance

    # Encoder Architecture (Wide-Stream BiGRU)
    HIDDEN_SIZE = 384  # Width of the residual stream
    NUM_LAYERS = 6  # Number of Residual BiGRU Blocks
    DROPOUT = 0.1

    # ==========================
    # Target Configuration
    # ==========================
    # The 3 columns actually scored by the metric.
    # We train ONLY on these to avoid noise from deg_pH10 and deg_50C.
    TARGET_COLS = ["reactivity", "deg_Mg_pH10", "deg_Mg_50C"]
    NUM_TARGETS = 3

    # All columns required in the submission file
    SUBMISSION_COLS = ["reactivity", "deg_Mg_pH10", "deg_pH10", "deg_Mg_50C", "deg_50C"]

    # ==========================
    # Training Hyperparameters
    # ==========================
    BATCH_SIZE = 32
    LEARNING_RATE = 1e-3
    EPOCHS = 20

    # Stochastic Weight Averaging (SWA)
    # We average checkpoints from the last N epochs.
    # If EPOCHS=20, start at 15 to average 15, 16, 17, 18, 19 (0-indexed).
    SWA_START_EPOCH = 15

    # Optimization
    WEIGHT_DECAY = 1e-4
    MAX_GRAD_NORM = 1.0

    # Scheduler (Cosine Annealing)
    T_MAX = EPOCHS  # Cycle length matches total epochs
    ETA_MIN = 1e-6  # Minimum learning rate

    def __init__(self):
        """Initialize directory structures."""
        os.makedirs(self.WORKING_DIR, exist_ok=True)
        os.makedirs(self.SUBMISSION_DIR, exist_ok=True)
